<div x-data="{ last: 'Just now', failed: false, timer: null, destroy() { clearInterval(this.timer); } }"
     x-init="let busy = false; timer = setInterval(async () => { if (document.hidden || busy) return; busy = true; try { const r = await fetch(@js(route('activity.metrics')), { headers: { Accept: 'application/json' }, cache: 'no-store' }); if (!r.ok) throw new Error(); const data = await r.json(); for (const card of document.querySelectorAll('[data-activity-app]')) { const row = data.apps[card.dataset.activityApp]; if (!row) continue; for (const n of card.querySelectorAll('[data-count]')) n.textContent = row[n.dataset.count]; const s = card.querySelector('[data-stale]'); if (s) s.textContent = row.stale; } for (const key of ['online', 'today']) { const n = document.querySelector('[data-total=' + key + ']'); if (n) n.textContent = Object.values(data.apps).reduce((sum, row) => sum + row[key], 0); } last = new Date(data.refreshedAt).toLocaleTimeString(); failed = false; } catch { failed = true; } finally { busy = false; } }, 30000);">
    <p class="portal-muted text-xs"><span x-show="!failed">Counts refreshed: <span x-text="last"></span> · every 30 seconds</span><span x-show="failed" x-cloak>Unable to refresh counts. Showing last available figures.</span></p>
</div>
